const D = { density:.5, energy:.6, speed:1, scale:1, hue:210, x:.5, y:.5, warp:.6, style:'vasarely', act:'orbit', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style;
const vasa=style==='vasarely', moire=style==='moire', half=style==='halftone', therm=style==='thermal';
const hue=md(P.hue,360);
const dens=clp(P.density,0,1);
const en=clp(P.energy,0,1);
const intens=.55+.6*K.intensity;

// grid fineness from density (FIRST poke param — structural, obvious change)
const N=Math.round(8+dens*15);
const cell=u/N;
const cols=Math.ceil(W/cell)+1, rows=Math.ceil(Hh/cell)+1;

// warp amplitude (SECOND poke param via energy) + independent warp radius/strength
const warp=clp(P.warp,0,1);
const amp=(.3+.9*en)*intens*(.4+warp);           // magnification depth
const R=u*(.24+.5*warp);                          // lens radius
const spd=P.speed;

// ---- bulge center: orbits continuously on K.t (real-time motion floor, never rephases) ----
const drift=K.t*0.055*spd;
let ox,oy,orbR=u*(.12+.16*warp);
if(P.act==='pulse'){                              // bulge snaps between anchors on the beat
  const idx=Math.floor(K.beat*spd);
  ox=W*(.5+.30*Math.sin(idx*2.399+P.seed))+u*0.03*Math.sin(K.t*.7);
  oy=Hh*(.5+.30*Math.cos(idx*1.717+P.seed))+u*0.03*Math.cos(K.t*.6);
}else if(P.act==='breathe'){                      // bulge stays central, radius pumps
  ox=P.x*W+u*0.05*Math.sin(K.t*.3);
  oy=P.y*Hh+u*0.05*Math.cos(K.t*.27);
}else{                                            // orbit (default)
  ox=P.x*W+orbR*Math.cos(drift+P.seed*0.7);
  oy=P.y*Hh+orbR*0.72*Math.sin(drift*1.13+P.seed*0.4);
}
const breath=P.act==='breathe'? (0.55+0.7*(0.5+0.5*Math.sin(K.t*.6))) : 1;
const beatMag=1+(0.35*K.pulse+0.45*A.bass)*intens;   // pop on the kick, audio on top
const ampF=amp*breath*beatMag;

// heat ramp for thermal false-color
function heat(t){t=clp(t,0,1);
  if(t<.25){const k=t/.25;return[md(250-40*k,360),85-15*k,18+40*k];}
  if(t<.5){const k=(t-.25)/.25;return[md(210-120*k,360),80,58+22*k];}
  if(t<.75){const k=(t-.5)/.25;return[md(330+ (30*k),360),85-25*k,80+15*k];}
  const k=(t-.75)/.25;return[md(15+40*k,360),60-45*k,95+5*k];
}

// backdrop
noStroke();
if(vasa){ background(hue,6,7); }
else if(moire){ background(hue,20,6); }
else if(half){ background(md(hue+8,360),12,93); }
else { background(245,70,7); }

rectMode(CENTER);
const lw=cell*clp(P.scale,.4,2);
const swf=K.swell;

for(let j=0;j<rows;j++){
  const gy=(j+0.5)*cell;
  for(let i=0;i<cols;i++){
    const gx=(i+0.5)*cell;
    const dx=gx-ox, dy=gy-oy, d=Math.hypot(dx,dy)+1e-4;
    const g=Math.exp(-(d*d)/(R*R));               // gaussian bump
    const m=1+ampF*g;                             // magnification near bulge
    const push=ampF*g*R*0.28;                     // slight outward displacement -> dome
    const nx=gx+(dx/d)*push, ny=gy+(dy/d)*push;
    const rot=g*ampF*1.15 + (moire?0:0);          // twist grid into the lens
    const sz=lw*m;
    if(nx<-cell||nx>W+cell||ny<-cell||ny>Hh+cell) continue;

    const par=(i+j)&1;
    const twist=rot>0.02;                          // only pay push/pop where the lens twists
    if(twist){ push(); translate(nx,ny); rotate(rot); }
    const dx0=twist?0:nx, dy0=twist?0:ny;          // draw at origin when transformed, else in-place
    if(vasa){
      // hard-edge b&w squares; brightness graded across the dome for tonal sphere
      const shade=par? clp(96-46*g,10,96) : clp(8+40*g,4,70);
      noStroke(); fill(hue,par?5:10,shade); rect(dx0,dy0,sz*0.98,sz*0.98);
    } else if(moire){
      // interference banding: brightness = high-freq fn of warped distance -> shimmering moire
      const band=0.5+0.5*Math.sin(d*(0.16+0.05*dens) - K.t*1.3*spd + g*7);
      const b2=0.5+0.5*Math.sin(d*0.09 + K.t*0.6 + par*3.14);
      const bb=clp(14+82*band*b2,3,97);
      noStroke(); fill(md(hue+ band*40,360), 24+50*g, bb); rect(dx0,dy0,sz*0.96,sz*0.96);
    } else if(half){
      // halftone screen: dot radius from field -> dome reads as a bright bulge
      const dotr=sz*0.5*(0.14+0.9*(1-g*0.85));
      noStroke(); fill(md(hue+4,360), 14, 16); circle(dx0,dy0,dotr);
    } else {
      // thermal false-color by bulge magnitude + radial base gradient
      const base=clp(0.16 + g*0.8 + 0.12*Math.sin(d*0.02 - K.t*0.5),0,1);
      const c=heat(base);
      noStroke(); fill(c[0],c[1],c[2]); rect(dx0,dy0,sz*0.99,sz*0.99);
    }
    if(twist) pop();
  }
}

// faint specular highlight rim so the sphere reads (few shapes, ADD)
if(!half){
  blendMode(ADD);
  const hb=therm?55: (moire? md(hue+60,360): (vasa?hue:hue));
  const hl=u*(0.05+0.10*ampF);
  drawingContext.shadowBlur=0;
  for(let k=3;k>=1;k--){ noStroke(); fill(hb, therm?20:12, 100, (therm?7:9)*(0.5+0.6*en)*k/3); circle(ox-hl*0.4,oy-hl*0.4, hl*k*1.3*(0.7+0.5*swf)); }
  // treble sparkle riding the rim
  if(A.treble>0.05){ const ns=Math.floor(14*A.treble); for(let s=0;s<ns;s++){ const a=fr(s*3.3+Math.floor(K.beat*2))*TAU; fill(hb,20,100,50*A.treble); circle(ox+Math.cos(a)*R*0.7, oy+Math.sin(a)*R*0.7, u*0.006); } }
  blendMode(BLEND);
}
rectMode(CORNER);
drawingContext.shadowBlur=0;
